WITH filtered AS (SELECT *, UPPER(account_type) account_type_upper, DATE_TRUNC('week', opened_date) opened_date_period FROM accounts WHERE customer_id IS NOT NULL AND status IS DISTINCT FROM 'CLOSED') SELECT CASE WHEN balance >= 76000 THEN 'HIGH' ELSE 'LOW' END AS balance_tier, customer_id, DATE_TRUNC('YEAR', opened_date_period) AS year_start, APPROX_PERCENTILE(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN account_type = 'SAVINGS' THEN 1 END), 0), 2) AS balance_per_savings, COUNT(CASE WHEN account_type = 'CHECKING' THEN 1 END) AS checking_count, SIZE(COLLECT_SET(status)) AS num_status, SIZE(COLLECT_SET(account_type)) AS num_account_types, COUNT_IF(account_type = 'SAVINGS') AS savings_events, GROUPING_ID() AS grouping_id FROM filtered GROUP BY ROLLUP (CASE WHEN balance >= 76000 THEN 'HIGH' ELSE 'LOW' END, customer_id, DATE_TRUNC('YEAR', opened_date_period)) ORDER BY num_account_types ASC;
